head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.vScrenID = "ULDSTF05630.xml";
scwin.vSecugrpID = SECUGRP_ID_BC;
scwin.vMktId = $c.lc.fn_getMktId();
scwin.vBzProcsNo = "";
scwin.vIsurCd = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetPar = function(arrPar) {
    arrPar[0] = $c.stf.getObjectValue(txb_ISU_CD);
    arrPar[1] = $c.stf.getObjectValue(txb_ISU_NM);
    arrPar[2] = scwin.vSecugrpID;
    arrPar[3] = scwin.vMktId;
    arrPar[4] = scwin.vBzProcsNo;
    arrPar[5] = scwin.vIsurCd;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetPar = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_NM);
        scwin.vIsurCd = arrPar[0].ISUR_CD;
        btn_Search.trigger("onclick");
    }
};
scwin.fn_OpenDetail = async function(row) {
    if (row > 0) {
        scwin.fn_setBzProcsNo(row);
    } else {
        scwin.vBzProcsNo = "";
    }
    await $c.frame.CreateDialogFrame("ULDSTF05631.gfm", "/lstproc/ULDSTF05631.gfm", $c.lc.fn_getSecuGrpNm(scwin.vSecugrpID) + " 존립기간 변경관리", 200, 200, 665 + 2, 360, "");
};
scwin.fn_setBzProcsNo = function(obj) {
    scwin.vBzProcsNo = dts_List.getCellData(eval(obj), "BZ_PROCS_NO");
};
scwin.fn_list_sync = function() {
    var url = "/fiscalYearChange.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=exstlistMarketBC&inputMessageId=FISCYY_CHG_INOUT&ISU_CD=" + $c.stf.getObjectValue(txb_ISU_CD);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    $c.cm.ShowWin(grd_List);
};
scwin.fn_list_sync2 = function() {
    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=FISCYY_CHG_LIST_ISU_BC" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.existencebc.select.updateall" + "&{P}param01=" + $c.stf.getObjectValue(edt_MKTACT_ENFORCE_DD) + "&{P}param02=" + $c.stf.getObjectValue(edt_MKTACT_ENFORCE_DD);
    dts_ListChgHist.DataID = encodeURI(url);
    dts_ListChgHist.reset();
    $c.cm.ShowWin(grd_ListChgHist);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.dts_ListChgHist_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page3);
    $c.cm.CloseWin(rowcount, grd_ListChgHist);
};
scwin.img_ISU_NM_onclick = function() {
    $c.lc.fn_PopFindIsu(SECUGRP_ID_BC);
};
scwin.btn_New_onclick = function() {
    if ($c.stf.getObjectValue(txb_ISU_NM) == "") {
        $c.win.alert("[종목]을 선택하세요.");
    } else {
        scwin.fn_OpenDetail(-999);
    }
};
scwin.grd_List_OnDblClick = function(row, colid) {
    scwin.fn_OpenDetail(row);
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.getObjectValue(txb_ISU_NM) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_NM.focus();
    } else {
        scwin.fn_list_sync();
    }
};
scwin.btn_srchChgHist_onclick = function() {
    scwin.fn_list_sync2();
};
scwin.img_Excel_onclick = function() {
    if (dts_List.getTotalRow() > 0) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, $c.lc.fn_getSecuGrpNm(scwin.vSecugrpID) + " 존립기간변경목록", "", "8");
    }
    if (dts_ListChgHist.getTotalRow() > 0) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_ListChgHist, $c.lc.fn_getSecuGrpNm(scwin.vSecugrpID) + " 신탁기간 만료일 정정사항", "", "8");
    }
    if (dts_List.getTotalRow() == 0 && dts_ListChgHist.getTotalRow() == 0) {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_MKTACT_ENFORCE_DD_onclick = function() {
    popUpCalendar2(edt_MKTACT_ENFORCE_DD);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_list_sync2();
};
scwin.img_MKTACT_ENFORCE_DD_onclick = function() {
    popUpCalendar2(edt_MKTACT_ENFORCE_DD);
};
scwin.grd_ListChgHist_OnDblClick = function(row, colid) {
    txb_ISU_CD.setValue(dts_ListChgHist.getCellData(row, "ISU_CD"));
    txb_ISU_NM.setValue(dts_ListChgHist.getCellData(row, "ISU_KOR_NM"));
    scwin.vIsurCd = dts_ListChgHist.getCellData(row, "ISUR_CD");
    btn_Search.trigger("onclick");
};
